      // Chronological placement is automatic. proEntries sorts every EXPERIENCE entry by end date (Present first),
      // then by start date, newest first. Mark exactly one current role primary:true to pin it on top; mark tail:true to keep an entry at the bottom of the list.
      // New entries can be pasted ANYWHERE in the EXPERIENCE array and land in the right spot at load.
      function expSpan(e) {
        var MO = {
          jan: 1,
          feb: 2,
          mar: 3,
          apr: 4,
          may: 5,
          jun: 6,
          jul: 7,
          aug: 8,
          sep: 9,
          oct: 10,
          nov: 11,
          dec: 12,
        };
        var parts = (e.dates || "").split("\u2013");
        var rawS = (parts[0] || "").trim();
        var rawE = (
          parts.length > 1 ? parts[parts.length - 1] : parts[0] || ""
        ).trim();
        function key(str, fbYear) {
          if (/present/i.test(str)) return 999912;
          var mm = str.match(/([A-Za-z]{3})/);
          var yy = str.match(/(\d{4})/);
          var mo = mm ? MO[mm[1].toLowerCase()] || 0 : 0;
          var yr = yy ? parseInt(yy[1], 10) : fbYear || 0;
          return yr * 100 + mo;
        }
        var end = key(rawE, 0);
        var start = key(rawS, Math.floor(end / 100));
        return { start: start, end: end };
      }
      function sortExperience(arr) {
        return arr.slice().sort(function (a, b) {
          var pa = a.primary ? 1 : 0,
            pb = b.primary ? 1 : 0;
          if (pb !== pa) return pb - pa;
          var ta = a.tail ? 1 : 0,
            tb = b.tail ? 1 : 0;
          if (ta !== tb) return ta - tb;
          var A = expSpan(a),
            B = expSpan(b);
          if (B.end !== A.end) return B.end - A.end;
          return B.start - A.start;
        });
      }
      const proEntries = sortExperience(EXPERIENCE);
      const sportsEntries = EXPERIENCE.filter((e) => e.type === "sports");

