      function openLearningApp(app) {
        var w = null;
        try {
          w = window.open("about:blank", "_blank");
        } catch (e) {}
        var land = function (url) {
          if (w && !w.closed) {
            w.location = url;
          } else {
            window.open(url, "_blank");
          }
        };
        var toEmbedded = function () {
          try {
            var b64 = app.gz ? window[app.gz] : null;
            if (!b64 || typeof DecompressionStream === "undefined") {
              land(app.url);
              return;
            }
            var bin = atob(b64);
            var bytes = new Uint8Array(bin.length);
            for (var i = 0; i < bin.length; i++) {
              bytes[i] = bin.charCodeAt(i);
            }
            var stream = new Blob([bytes])
              .stream()
              .pipeThrough(new DecompressionStream("gzip"));
            new Response(stream).blob().then(
              function (bl) {
                var url = URL.createObjectURL(
                  new Blob([bl], { type: "text/html" }),
                );
                land(url);
                setTimeout(function () {
                  URL.revokeObjectURL(url);
                }, 60000);
              },
              function () {
                land(app.url);
              },
            );
          } catch (e) {
            land(app.url);
          }
        };
        fetch(app.url, { method: "HEAD" }).then(function (r) {
          if (r.ok) {
            land(app.url);
          } else {
            toEmbedded();
          }
        }, toEmbedded);
      }

