      function Contact() {
        const [f, setF] = useState({ name: "", email: "", message: "" });
        const [sent, setSent] = useState(false);
        const [sending, setSending] = useState(false);
        const [err, setErr] = useState("");
        const submit = async () => {
          if (!f.name || !f.email || !f.message) {
            alert("Please fill in all fields.");
            return;
          }

          setSending(true);
          setErr("");

          try {
            const res = await fetch("https://formspree.io/f/xzdlleoe", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Accept: "application/json",
              },
              body: JSON.stringify({
                name: f.name.trim(),
                email: f.email.trim(),
                message: f.message.trim(),
                _subject: "Portfolio contact from " + f.name.trim(),
              }),
            });

            const data = await res.json().catch(() => ({}));

            if (!res.ok) {
              const msg =
                data && data.errors && data.errors.length
                  ? data.errors.map((e) => e.message).join(" ")
                  : data.error || "Message could not be sent.";
              throw new Error(msg);
            }
          } catch (e) {
            setErr(
              e && e.message
                ? e.message
                : "Message could not be sent. Please email Dustin directly.",
            );
            setSending(false);
            return;
          }

          setSending(false);
          setSent(true);
        };
        return (
          <div className="page">
            <div className="wrap">
              <SecHead
                eyebrow="Get In Touch"
                title="Say Hello"
                lead="Questions about the Navy, the apps, hockey, or anything else? Drop a note or reach out directly."
              />
              <div className="contact-grid">
                <div>
                  {sent ? (
                    <div
                      style={{
                        padding: "30px 24px",
                        border: "1px solid var(--gold)",
                        borderRadius: 12,
                        textAlign: "center",
                        background: "rgba(201,168,76,.06)",
                      }}
                    >
                      <div
                        style={{
                          fontFamily: "var(--fdisp)",
                          fontWeight: 800,
                          fontSize: 24,
                          color: "var(--gold)",
                        }}
                      >
                        Message Sent
                      </div>
                      <p style={{ marginTop: 10, fontSize: 14, opacity: 0.85 }}>
                        Thanks, {f.name.split(" ")[0]}. Your message has been
                        sent to Dustin's inbox.
                      </p>
                      <button
                        className="btn btn-ghost btn-sm"
                        style={{ marginTop: 16 }}
                        onClick={() => {
                          setSent(false);
                          setF({ name: "", email: "", message: "" });
                        }}
                      >
                        Send another
                      </button>
                    </div>
                  ) : (
                    <div>
                      <div className="field">
                        <label>Name</label>
                        <input
                          value={f.name}
                          onChange={(e) => setF({ ...f, name: e.target.value })}
                          placeholder="Your name"
                        />
                      </div>
                      <div className="field">
                        <label>Email</label>
                        <input
                          type="email"
                          value={f.email}
                          onChange={(e) =>
                            setF({ ...f, email: e.target.value })
                          }
                          placeholder="you@example.com"
                        />
                      </div>
                      <div className="field">
                        <label>Message</label>
                        <textarea
                          value={f.message}
                          onChange={(e) =>
                            setF({ ...f, message: e.target.value })
                          }
                          placeholder="What's on your mind?"
                        />
                      </div>
                      <button
                        className="btn btn-gold"
                        onClick={submit}
                        disabled={sending}
                      >
                        {sending ? "Sending..." : "Send Message"}
                      </button>
                      {err && <div className="notice">{err}</div>}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        );
      }

      /* ============================================================
   ADMIN KEY MODAL
============================================================ */
      function KeyModal({ onClose, onSuccess }) {
        const [v, setV] = useState("");
        const [shake, setShake] = useState(false);
        const submit = () => {
          if (v.trim().toLowerCase() === SITE.adminKey.toLowerCase()) {
            onSuccess();
          } else {
            setShake(true);
            setV("");
            setTimeout(() => setShake(false), 400);
          }
        };
        return (
          <div className="modal-bg" onClick={onClose}>
            <div
              className="modal"
              style={{ maxWidth: 420 }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="modal-body">
                <div className="key-wrap">
                  <svg
                    className="kico"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.5"
                  >
                    <circle cx="8" cy="15" r="4" />
                    <path d="M10.8 12.2 20 3M17 6l3 3M15 8l2 2" />
                  </svg>
                  <div
                    style={{
                      fontFamily: "var(--fdisp)",
                      fontWeight: 800,
                      fontSize: 24,
                      marginBottom: 6,
                    }}
                  >
                    Access Key
                  </div>
                  <p
                    style={{ fontSize: 13.5, opacity: 0.75, marginBottom: 18 }}
                  >
                    You found it. Enter the key to unlock admin controls.
                  </p>
                  <input
                    className={"key-in" + (shake ? " shake" : "")}
                    value={v}
                    autoFocus
                    onChange={(e) => setV(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && submit()}
                    placeholder="•••••"
                  />
                  <div
                    style={{
                      display: "flex",
                      gap: 10,
                      justifyContent: "center",
                    }}
                  >
                    <button className="btn btn-ghost btn-sm" onClick={onClose}>
                      Cancel
                    </button>
                    <button className="btn btn-gold btn-sm" onClick={submit}>
                      Unlock
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      }

      /* ============================================================
   RESUME COMPILER
============================================================ */
      const SECTION_DEFS = [
        { key: "cover", t: "Cover Letter", d: "Company, position, and body" },
        { key: "resume", t: "Résumé", d: "Pick roles + choose a style" },
        {
          key: "docs",
          t: "Supporting Documents",
          d: "Attach certificates & transcripts",
        },
        { key: "refs", t: "References", d: "Up to 3 professional references" },
      ];

      /* ============================================================
   CUSTOM TAILORING  —  job posting -> tailored cover letter + resume
   Added feature. Engine order: Cloudflare Worker -> direct Claude
   (sandbox/preview only) -> offline heuristic demo. Output is a
   letterhead cover letter plus a tailored resume capped at 2 pages.
============================================================ */

      /* ---- signature font (embedded, subset Great Vibes, OFL) ---- */
      function registerSignatureFont(doc) {
        if (window.SIG_FONT) {
          try {
            doc.addFileToVFS("GreatVibes.ttf", window.SIG_FONT);
            doc.addFont("GreatVibes.ttf", "GreatVibes", "normal");
            return true;
          } catch (e) {
            return false;
          }
        }
        return false;
      }

      /* ---- shared letterhead used by both cover letter and tailored resume ---- */
      function drawLetterhead(doc, subtitle) {
        var W = 612,
          M = 54;
        try {
          doc.addImage(LOGO_SRC, "PNG", M, 38, 48, 48);
        } catch (e) {}
        doc.setFont("helvetica", "bold");
        doc.setFontSize(22);
        doc.setTextColor(13, 27, 42);
        doc.text("Dustin Burich", M + 60, 60);
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(90, 90, 90);
        doc.text(
          phoneText + "     " + SITE.email + "     " + SITE.location,
          M + 60,
          76,
        );
        doc.setDrawColor(201, 168, 76);
        doc.setLineWidth(2);
        doc.line(M, 96, W - M, 96);
        var y = 118;
        if (subtitle) {
          doc.setFont("helvetica", "bold");
          doc.setFontSize(11);
          doc.setTextColor(14, 116, 144);
          doc.text(subtitle, M, y);
          y += 20;
        }
        return y;
      }
      function tailoredFoot(doc) {
        doc.setFont("helvetica", "italic");
        doc.setFontSize(8);
        doc.setTextColor(150, 150, 150);
        doc.text(SITE.pdfFooter, 306, 762, { align: "center" });
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(40, 40, 40);
      }

      /* ---- cover letter page (letterhead + body + script signature) ---- */
      function coverLetterBytes(opts) {
        var jsPDF = window.jspdf.jsPDF;
        var doc = new jsPDF({ unit: "pt", format: "letter" });
        var hasSig = registerSignatureFont(doc);
        var W = 612,
          M = 54;
        var y = drawLetterhead(doc, null);
        y += 4;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(40, 40, 40);
        var date = new Date().toLocaleDateString("en-US", {
          year: "numeric",
          month: "long",
          day: "numeric",
        });
        doc.text(date, M, y);
        y += 22;
        if (opts.company) {
          doc.setFont("helvetica", "bold");
          doc.text(opts.company, M, y);
          y += 15;
          doc.setFont("helvetica", "normal");
        }
        if (opts.position) {
          doc.text("Re: " + opts.position, M, y);
          y += 20;
        }
        var body = opts.coverBody || "Dear Hiring Team,";
        doc.setFontSize(10.5);
        doc.setTextColor(40, 40, 40);
        var lines = doc.splitTextToSize(body, W - M * 2);
        lines.forEach(function (ln) {
          if (y > 688) {
            tailoredFoot(doc);
            doc.addPage();
            y = 64;
          }
          doc.text(ln, M, y);
          y += 15.5;
        });
        y += 12;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10.5);
        doc.setTextColor(40, 40, 40);
        doc.text("Respectfully,", M, y);
        if (hasSig) {
          doc.setFont("GreatVibes", "normal");
          doc.setFontSize(30);
          doc.setTextColor(13, 27, 42);
          doc.text("Dustin Burich", M, y + 34);
        } else {
          doc.setFont("times", "italic");
          doc.setFontSize(22);
          doc.setTextColor(13, 27, 42);
          doc.text("Dustin Burich", M, y + 30);
        }
        y += 50;
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(13, 27, 42);
        doc.text("Dustin Burich", M, y);
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(90, 90, 90);
        doc.text(SITE.location, M, y + 13);
        tailoredFoot(doc);
        return doc.output("arraybuffer");
      }

      /* ---- cert lookup by title (exact then loose contains) ---- */
      function certsByTitles(titles) {
        var out = [];
        if (!titles) {
          return out;
        }
        for (var i = 0; i < titles.length; i++) {
          var want = ("" + titles[i]).toLowerCase().trim(),
            hit = null;
          for (var j = 0; j < CERTS.length; j++) {
            if (CERTS[j].t.toLowerCase() === want) {
              hit = CERTS[j];
              break;
            }
          }
          if (!hit) {
            for (var k = 0; k < CERTS.length; k++) {
              var ct = CERTS[k].t.toLowerCase();
              if (ct.indexOf(want) >= 0 || want.indexOf(ct) >= 0) {
                hit = CERTS[k];
                break;
              }
            }
          }
          if (hit && out.indexOf(hit) < 0) {
            out.push(hit);
          }
        }
        return out;
      }

      /* ---- tailored resume, rendered into a fresh doc at a given density ---- */
      function renderTailoredResume(opts, maxBullets, roleIds) {
        var jsPDF = window.jspdf.jsPDF;
        var doc = new jsPDF({ unit: "pt", format: "letter" });
        var W = 612,
          M = 54;
        var y = drawLetterhead(doc, "Professional Résumé");
        var ensure = function (space) {
          if (y > 720 - space) {
            tailoredFoot(doc);
            doc.addPage();
            y = 64;
          }
        };
        var sectionHead = function (label) {
          ensure(30);
          doc.setFont("helvetica", "bold");
          doc.setFontSize(12);
          doc.setTextColor(14, 116, 144);
          doc.text(label.toUpperCase(), M, y);
          doc.setDrawColor(14, 116, 144);
          doc.setLineWidth(1.2);
          doc.line(M, y + 5, W - M, y + 5);
          y += 20;
        };
        if (opts.summary) {
          doc.setFont("helvetica", "italic");
          doc.setFontSize(9.5);
          doc.setTextColor(60, 60, 60);
          var sl = doc.splitTextToSize(opts.summary, W - M * 2);
          sl.forEach(function (ln) {
            ensure(14);
            doc.text(ln, M, y);
            y += 13;
          });
          y += 10;
        }
        var DISP = [
          "c1",
          "e6",
          "e5",
          "e4",
          "e3",
          "e2",
          "e1",
          "e0",
          "s1",
          "s2",
          "s3",
        ];
        var roles = EXPERIENCE.filter(function (e) {
          return roleIds.indexOf(e.id) >= 0;
        }).sort(function (a, b) {
          return DISP.indexOf(a.id) - DISP.indexOf(b.id);
        });
        if (roles.length) {
          sectionHead("Professional Experience");
          roles.forEach(function (r) {
            ensure(40);
            doc.setFont("helvetica", "bold");
            doc.setFontSize(11);
            doc.setTextColor(13, 27, 42);
            doc.text(r.title, M, y);
            doc.setFont("helvetica", "normal");
            doc.setFontSize(9);
            doc.setTextColor(120, 120, 120);
            doc.text(r.dates, W - M, y, { align: "right" });
            y += 13;
            doc.setFont("helvetica", "bold");
            doc.setFontSize(9.5);
            doc.setTextColor(14, 116, 144);
            doc.text(r.org + "  ·  " + r.loc, M, y);
            y += 13;
            doc.setFont("helvetica", "normal");
            doc.setFontSize(9.5);
            doc.setTextColor(50, 50, 50);
            var bl = r.bullets.slice(0, maxBullets);
            bl.forEach(function (b) {
              doc.setFont("helvetica", "normal");
              doc.setFontSize(9.5);
              doc.setTextColor(50, 50, 50);
              var ls = doc.splitTextToSize("•  " + b, W - M * 2 - 6);
              ls.forEach(function (ln) {
                ensure(13);
                doc.setFont("helvetica", "normal");
                doc.text(ln, M + 4, y);
                y += 12.5;
              });
            });
            y += 9;
          });
        }
        var certs = certsByTitles(opts.certTitles).filter(function (c) {
          return !c.ack;
        });
        if (certs.length) {
          sectionHead("Certifications & Training");
          doc.setFont("helvetica", "normal");
          doc.setFontSize(9.5);
          doc.setTextColor(50, 50, 50);
          certs.forEach(function (c) {
            ensure(13);
            doc.setFont("helvetica", "bold");
            doc.setTextColor(40, 40, 40);
            doc.setFontSize(9.5);
            var head = "•  " + c.t;
            doc.text(doc.splitTextToSize(head, W - M * 2 - 6)[0], M + 4, y);
            doc.setFont("helvetica", "normal");
            doc.setTextColor(120, 120, 120);
            doc.setFontSize(8.5);
            doc.text(c.iss, W - M, y, { align: "right" });
            y += 13;
          });
          y += 4;
        }
        sectionHead("Education");
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9.5);
        doc.setTextColor(40, 40, 40);
        ensure(13);
        doc.text("•  Associate of Arts, Liberal Arts", M + 4, y);
        doc.setFont("helvetica", "normal");
        doc.setTextColor(120, 120, 120);
        doc.setFontSize(8.5);
        doc.text("Saint Leo University · GPA 3.3 · 2016", W - M, y, {
          align: "right",
        });
        y += 13;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(90, 90, 90);
        ensure(12);
        doc.text(
          "    Joint Services Transcript: 78 ACE-recommended credit hours · Two U.S. Dept. of Labor apprenticeships",
          M + 4,
          y,
        );
        y += 12;
        tailoredFoot(doc);
        return doc;
      }

      /* ---- fit the resume to a hard 2-page ceiling ---- */
      function tailoredResumeBytes(opts) {
        var ids =
          opts.roleIds && opts.roleIds.length
            ? opts.roleIds.slice()
            : ["c1", "e6", "e3", "e2"];
        var mb, keep, d;
        for (mb = 5; mb >= 2; mb--) {
          d = renderTailoredResume(opts, mb, ids);
          if (d.getNumberOfPages() <= 2) {
            return d.output("arraybuffer");
          }
        }
        for (keep = ids.length; keep >= 2; keep--) {
          d = renderTailoredResume(opts, 3, ids.slice(0, keep));
          if (d.getNumberOfPages() <= 2) {
            return d.output("arraybuffer");
          }
        }
        d = renderTailoredResume(opts, 2, ids.slice(0, 3));
        while (d.getNumberOfPages() > 2) {
          d.deletePage(d.getNumberOfPages());
        }
        return d.output("arraybuffer");
      }

      async function mergePdfBytes(list) {
        var PDFDocument = PDFLib.PDFDocument;
        var out = await PDFDocument.create();
        for (var i = 0; i < list.length; i++) {
          var src = await PDFDocument.load(list[i]);
          var pgs = await out.copyPages(src, src.getPageIndices());
          pgs.forEach(function (p) {
            out.addPage(p);
          });
        }
        return await out.save();
      }

      async function buildTailoredPackage(opts) {
        var list = [];
        if (opts.include.cover) {
          list.push(coverLetterBytes(opts));
        }
        if (opts.include.resume) {
          list.push(tailoredResumeBytes(opts));
        }
        if (list.length === 0) {
          throw new Error("Turn on the cover letter or the résumé first.");
        }
        var finalBytes =
          list.length === 1 ? list[0] : await mergePdfBytes(list);
        var tag = opts.company
          ? "_" + opts.company.replace(/[^a-z0-9]/gi, "")
          : "";
        downloadBytes(finalBytes, "Dustin_Burich_Tailored" + tag + ".pdf");
      }

      /* ---- profile payload sent to the model / worker ---- */
      function tailorProfile() {
        return {
          roles: EXPERIENCE.map(function (e) {
            return {
              id: e.id,
              title: e.title,
              org: e.org,
              dates: e.dates,
              type: e.type,
              focus: e.tags,
              skills: e.quals,
              highlights: e.bullets,
            };
          }),
          certifications: CERTS.filter(function (c) {
            return c.status === "active" && !c.ack;
          }).map(function (c) {
            return { title: c.t, issuer: c.iss, tier: c.tier };
          }),
          education: [
            "Associate of Arts, Liberal Arts, Saint Leo University, 2016",
            "Joint Services Transcript, 78 ACE credit hours",
            "Two U.S. Department of Labor apprenticeships",
          ],
        };
      }
      function tailorSystemPrompt() {
        return [
          "You tailor Dustin Burich's real résumé and write his cover letters for a specific job posting.",
          "You are given his complete verified experience and certifications as JSON, plus the posting.",
          "Rules:",
          "1. Never invent facts, employers, dates, numbers, titles, or skills. Only select, prioritize, and lightly rephrase from the provided material.",
          "2. Choose the roles and certifications most relevant to the posting. Return role ids exactly from the provided list, and certification titles exactly as written. Select enough to fill about two pages, no more.",
          "3. Write the cover letter in Dustin's first-person voice: confident, plain, and human. It must begin with a salutation (Dear Hiring Team, or the named team) and end with its final paragraph. Do NOT add a closing, signature, or date, those are added automatically. No em dashes. No en dashes. No AI-sounding filler.",
          "4. Write a 2 to 3 sentence professional summary tailored to the posting, using only his real background.",
          "5. Output STRICT JSON only. No markdown, no backticks, no commentary. Match this shape exactly:",
          '{"company":"","position":"","summary":"","roleIds":[],"certTitles":[],"coverBody":""}',
          "coverBody uses \\n for line breaks.",
        ].join("\n");
      }
      function tailorUserPayload(input) {
        var posting = input.jobText
          ? input.jobText
          : "Job posting URL (fetch and read it): " + input.jobUrl;
        var hint = "";
        if (input.company) {
          hint += "\nKnown company: " + input.company;
        }
        if (input.position) {
          hint += "\nKnown position: " + input.position;
        }
        return (
          "JOB POSTING:\n" +
          posting +
          hint +
          "\n\nCANDIDATE PROFILE (JSON):\n" +
          JSON.stringify(tailorProfile()) +
          "\n\nReturn the JSON object now."
        );
      }
      function parseTailorJSON(text) {
        var t = ("" + text)
          .replace(/```json/g, "")
          .replace(/```/g, "")
          .trim();
        var s = t.indexOf("{"),
          e = t.lastIndexOf("}");
        if (s >= 0 && e > s) {
          t = t.slice(s, e + 1);
        }
        var data = JSON.parse(t);
        return {
          company: data.company || "",
          position: data.position || "",
          summary: data.summary || "",
          roleIds: Array.isArray(data.roleIds) ? data.roleIds : [],
          certTitles: Array.isArray(data.certTitles) ? data.certTitles : [],
          coverBody: data.coverBody || "",
        };
      }

      /* ---- engine: Cloudflare Worker ---- */
      async function workerTailor(input) {
        var res = await fetch(SITE.workerUrl.replace(/\/+$/, "") + "/tailor", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            jobUrl: input.jobUrl,
            jobText: input.jobText,
            company: input.company,
            position: input.position,
            profile: tailorProfile(),
          }),
        });
        if (!res.ok) {
          throw new Error("Worker returned " + res.status);
        }
        var data = await res.json();
        var out = data && data.result ? data.result : data;
        return {
          company: out.company || input.company || "",
          position: out.position || input.position || "",
          summary: out.summary || "",
          roleIds: out.roleIds || [],
          certTitles: out.certTitles || [],
          coverBody: out.coverBody || "",
          __engine: "worker",
        };
      }

      /* ---- engine: direct Claude call (works in the sandbox/preview) ---- */
      async function directTailor(input) {
        var res = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            model: "claude-sonnet-4-6",
            max_tokens: 2000,
            system: tailorSystemPrompt(),
            messages: [{ role: "user", content: tailorUserPayload(input) }],
          }),
        });
        if (!res.ok) {
          throw new Error("AI service returned " + res.status);
        }
        var data = await res.json();
        var text = (data.content || [])
          .filter(function (b) {
            return b.type === "text";
          })
          .map(function (b) {
            return b.text;
          })
          .join("\n");
        var parsed = parseTailorJSON(text);
        parsed.__engine = "ai";
        return parsed;
      }

      /* ---- engine: offline heuristic demo (no network) ---- */
      var TAILOR_STOP = (function () {
        var s = new Set();
        "the a an and or but for to of in on at by with from as is are was were be been being this that these those it its into over under out up down off will would can could should may might must not no do does did have has had you your our we they them their he she job role position work working experience years year team teams company organization required requirements responsibilities responsible ability able strong excellent good preferred plus etc via per across within about more most than then who what when where which will"
          .split(/\s+/)
          .forEach(function (w) {
            s.add(w);
          });
        return s;
      })();
      function tailorTokens(text) {
        var raw =
          ("" + (text || "")).toLowerCase().match(/[a-z][a-z+#]{1,}/g) || [];
        var out = [];
        for (var i = 0; i < raw.length; i++) {
          var w = raw[i];
          if (w.length < 3) {
            continue;
          }
          if (TAILOR_STOP.has(w)) {
            continue;
          }
          out.push(w);
        }
        return out;
      }
      function heuristicTailor(input) {
        var text = input.jobText || input.company + " " + input.position;
        var toks = tailorTokens(text);
        var freq = {};
        toks.forEach(function (w) {
          freq[w] = (freq[w] || 0) + 1;
        });
        var scoreText = function (str) {
          var t = tailorTokens(str),
            seen = {},
            sc = 0;
          for (var i = 0; i < t.length; i++) {
            if (freq[t[i]] && !seen[t[i]]) {
              seen[t[i]] = 1;
              sc += freq[t[i]];
            }
          }
          return sc;
        };
        var rScored = EXPERIENCE.map(function (e) {
          var base = scoreText(
            e.title +
              " " +
              e.tags.join(" ") +
              " " +
              e.quals.join(" ") +
              " " +
              e.bullets.join(" "),
          );
          var tagBoost = 0;
          e.tags.forEach(function (tg) {
            if (scoreText(tg) > 0) {
              tagBoost += 2;
            }
          });
          var cur = e.id === "c1" ? 6 : 0;
          return { id: e.id, s: base + tagBoost + cur, type: e.type };
        }).sort(function (a, b) {
          return b.s - a.s;
        });
        var roleIds = [];
        rScored.forEach(function (r) {
          if (roleIds.length < 5 && (r.s > 0 || r.id === "c1")) {
            roleIds.push(r.id);
          }
        });
        if (roleIds.indexOf("c1") < 0) {
          roleIds.unshift("c1");
          roleIds = roleIds.slice(0, 5);
        }
        var cScored = CERTS.filter(function (c) {
          return c.status === "active" && !c.ack;
        })
          .map(function (c) {
            var s = scoreText(c.t + " " + c.iss + " " + (c.desc || ""));
            var tierB = c.tier === 1 ? 1 : 0;
            return { t: c.t, s: s + tierB };
          })
          .sort(function (a, b) {
            return b.s - a.s;
          });
        var certTitles = [];
        cScored.forEach(function (c) {
          if (certTitles.length < 9 && c.s > 0) {
            certTitles.push(c.t);
          }
        });
        if (certTitles.length < 5) {
          cScored.forEach(function (c) {
            if (certTitles.length < 7 && certTitles.indexOf(c.t) < 0) {
              certTitles.push(c.t);
            }
          });
        }

        var THEMES = [
          {
            label: "security operations and force protection",
            kws: "security force protection access control law enforcement patrol surveillance antiterrorism guard safety emergency incident crisis threat screening investigation",
          },
          {
            label: "training and program management",
            kws: "training instructor curriculum onboarding mentor coach qualification develop development program facilitation teaching learning enablement",
          },
          {
            label: "customer success and account management",
            kws: "customer client success account stakeholder relationship retention support satisfaction adoption engagement enterprise",
          },
          {
            label: "project and operations management",
            kws: "project operations program coordinate logistics planning process tracking reporting kpi delivery schedule budget",
          },
          {
            label: "technology and AI enablement",
            kws: "ai azure cloud microsoft technical technology software systems data automation workflow digital",
          },
        ];
        var tScored = THEMES.map(function (th) {
          return { label: th.label, s: scoreText(th.kws) };
        }).sort(function (a, b) {
          return b.s - a.s;
        });
        var top = tScored
          .filter(function (t) {
            return t.s > 0;
          })
          .slice(0, 2)
          .map(function (t) {
            return t.label;
          });
        if (top.length === 0) {
          top = [
            "leadership and operations",
            "clear communication and accountability",
          ];
        }

        var co = input.company || "your organization";
        var pos = input.position || "this position";
        var p1 =
          "Dear Hiring Team,\n\nI am writing to apply for the " +
          pos +
          " role at " +
          co +
          ". After nearly twelve years of leadership in the United States Navy and a career since in customer success and program management, I bring a track record of leading teams, running complex operations, and delivering measurable results in demanding environments.";
        var p2 =
          "\n\nYour posting stands out to me because it lines up closely with my strengths in " +
          top[0] +
          (top[1] ? " and " + top[1] : "") +
          ". I have carried real accountability in each of these areas, always anchored in clear communication and a bias toward getting things done, and I am confident that same discipline would let me contribute quickly at " +
          co +
          ".";
        var p3 =
          "\n\nI would welcome the chance to talk through how my background fits what you are building. Thank you for your time and consideration.";
        return {
          company: input.company || "",
          position: input.position || "",
          summary: "",
          roleIds: roleIds,
          certTitles: certTitles,
          coverBody: p1 + p2 + p3,
          __engine: "demo",
        };
      }

      /* ---- the Custom Tailoring UI ---- */
      function CustomTailor() {
        var s0 = useState("");
        var company = s0[0],
          setCompany = s0[1];
        var s1 = useState("");
        var position = s1[0],
          setPosition = s1[1];
        var s2 = useState("");
        var jobUrl = s2[0],
          setJobUrl = s2[1];
        var s3 = useState("");
        var jobText = s3[0],
          setJobText = s3[1];
        var s4 = useState(false);
        var loading = s4[0],
          setLoading = s4[1];
        var s5 = useState(false);
        var building = s5[0],
          setBuilding = s5[1];
        var s6 = useState(null);
        var result = s6[0],
          setResult = s6[1];
        var s7 = useState("");
        var coverEdit = s7[0],
          setCoverEdit = s7[1];
        var s8 = useState("");
        var note = s8[0],
          setNote = s8[1];
        var s9 = useState("");
        var err = s9[0],
          setErr = s9[1];
        var sa = useState(true);
        var incCover = sa[0],
          setIncCover = sa[1];
        var sb = useState(true);
        var incResume = sb[0],
          setIncResume = sb[1];

        var generate = async function () {
          setErr("");
          setNote("");
          setResult(null);
          if (!jobText.trim() && !jobUrl.trim() && !position.trim()) {
            setErr(
              "Add a job posting URL, paste the description, or at least a position title.",
            );
            return;
          }
          setLoading(true);
          try {
            var input = {
              jobUrl: jobUrl.trim(),
              jobText: jobText.trim(),
              company: company.trim(),
              position: position.trim(),
            };
            var data;
            if (SITE.workerUrl) {
              data = await workerTailor(input);
            } else if (SITE.allowDirectAI && input.jobText) {
              try {
                data = await directTailor(input);
              } catch (e) {
                data = heuristicTailor(input);
                setNote(
                  "The AI service was not reachable here, so this used the offline template. It will use Claude through your Worker once deployed.",
                );
              }
            } else {
              data = heuristicTailor(input);
              if (!input.jobText && input.jobUrl) {
                setNote(
                  "This preview can't open external links on its own; that runs through your Cloudflare Worker once deployed. Paste the job description below to tailor with the real posting now.",
                );
              } else {
                setNote(
                  "Offline demo: matched your experience by keyword. Deployed, this drafts with Claude through your Worker.",
                );
              }
            }
            if (!data.company && input.company) {
              data.company = input.company;
            }
            if (!data.position && input.position) {
              data.position = input.position;
            }
            setResult(data);
            setCoverEdit(data.coverBody || "");
          } catch (e) {
            setErr(e.message || "Could not generate a tailored package.");
          }
          setLoading(false);
        };

        var download = async function () {
          if (!result) {
            return;
          }
          if (!incCover && !incResume) {
            setErr("Turn on the cover letter or the résumé to download.");
            return;
          }
          setErr("");
          setBuilding(true);
          try {
            await buildTailoredPackage({
              company: result.company,
              position: result.position,
              summary: result.summary,
              coverBody: coverEdit,
              roleIds: result.roleIds,
              certTitles: result.certTitles,
              include: { cover: incCover, resume: incResume },
            });
          } catch (e) {
            setErr("Could not build the PDF: " + (e.message || e));
          }
          setBuilding(false);
        };

        var pickedRoles = result
          ? EXPERIENCE.filter(function (e) {
              return result.roleIds.indexOf(e.id) >= 0;
            })
          : [];
        var pickedCerts = result ? certsByTitles(result.certTitles) : [];

        return (
          <div>
            {(loading || building) && (
              <Spinner
                label={building ? "Building your PDF" : "Tailoring to the role"}
              />
            )}
            <div className="tl-intro">
              Drop in a job posting and get back a cover letter on your
              letterhead plus a résumé tailored to the role, capped at two
              pages. The résumé pulls only from your real experience and
              certifications.
            </div>

            <div className="tl-grid">
              <div className="field">
                <label>
                  Company <span className="opt">optional</span>
                </label>
                <input
                  value={company}
                  onChange={function (e) {
                    setCompany(e.target.value);
                  }}
                  placeholder="e.g. Trego-Dugan Aviation"
                />
              </div>
              <div className="field">
                <label>
                  Position <span className="opt">optional</span>
                </label>
                <input
                  value={position}
                  onChange={function (e) {
                    setPosition(e.target.value);
                  }}
                  placeholder="e.g. Operations Manager"
                />
              </div>
            </div>
            <div className="field">
              <label>Job posting URL</label>
              <input
                value={jobUrl}
                onChange={function (e) {
                  setJobUrl(e.target.value);
                }}
                placeholder="https://…  (fetched by your Worker once deployed)"
              />
            </div>
            <div className="field">
              <label>
                Or paste the job description{" "}
                <span className="opt">
                  recommended, and required to tailor in this preview
                </span>
              </label>
              <textarea
                className="tl-jobtext"
                value={jobText}
                onChange={function (e) {
                  setJobText(e.target.value);
                }}
                placeholder="Paste the full posting text here for the sharpest tailoring."
              />
            </div>

            <div className="tl-actions">
              <button
                className="btn btn-gold"
                onClick={generate}
                disabled={loading}
              >
                {loading ? "Tailoring…" : "✦ Generate Tailored Package"}
              </button>
            </div>
            {err && <div className="tl-err">{err}</div>}

            {result && (
              <div className="tl-result">
                <div className="tl-detected">
                  <span className="achip">
                    <span className="anum">✓</span>
                    {result.position || "Position"}
                    {result.company ? " · " + result.company : ""}
                  </span>
                  <span
                    className={"tl-badge tl-" + (result.__engine || "demo")}
                  >
                    {result.__engine === "worker"
                      ? "Cloudflare Worker"
                      : result.__engine === "ai"
                        ? "Drafted with Claude"
                        : "Offline demo"}
                  </span>
                </div>
                {note && <div className="tl-note">{note}</div>}

                <div className="tl-block">
                  <div className="tl-block-h">
                    Cover letter{" "}
                    <span className="tl-sub">
                      editable · your monogram and signature are added
                      automatically
                    </span>
                  </div>
                  <textarea
                    className="tl-cover"
                    value={coverEdit}
                    onChange={function (e) {
                      setCoverEdit(e.target.value);
                    }}
                  />
                </div>

                <div className="tl-block">
                  <div className="tl-block-h">
                    Tailored résumé selection{" "}
                    <span className="tl-sub">
                      {pickedRoles.length} roles · {pickedCerts.length}{" "}
                      certifications · fit to 2 pages
                    </span>
                  </div>
                  <div className="tl-mini">Experience</div>
                  <div className="tl-chips">
                    {pickedRoles.map(function (r) {
                      return (
                        <span className="tl-chip" key={r.id}>
                          {r.title.split("—")[0].trim()} <em>{r.dates}</em>
                        </span>
                      );
                    })}
                  </div>
                  <div className="tl-mini" style={{ marginTop: 10 }}>
                    Certifications
                  </div>
                  <div className="tl-chips">
                    {pickedCerts
                      .filter(function (c) {
                        return !c.ack;
                      })
                      .map(function (c) {
                        return (
                          <span className="tl-chip alt" key={c.t}>
                            {c.t}
                          </span>
                        );
                      })}
                  </div>
                </div>

                <div className="tl-include">
                  <span className="tl-inc-lbl">Include in download:</span>
                  <span
                    className={"tl-toggle" + (incCover ? " on" : "")}
                    onClick={function () {
                      setIncCover(!incCover);
                    }}
                  >
                    <span className="li-cbox" />
                    Cover letter
                  </span>
                  <span
                    className={"tl-toggle" + (incResume ? " on" : "")}
                    onClick={function () {
                      setIncResume(!incResume);
                    }}
                  >
                    <span className="li-cbox" />
                    Tailored résumé
                  </span>
                </div>

                <div className="tl-actions">
                  <button
                    className="btn btn-ghost btn-sm"
                    onClick={generate}
                    disabled={loading}
                  >
                    ↺ Regenerate
                  </button>
                  <button
                    className="btn btn-gold"
                    onClick={download}
                    disabled={building}
                  >
                    {building ? "Building…" : "Open Tailored Package ↗"}
                  </button>
                </div>
              </div>
            )}
          </div>
        );
      }

      /* ---- hub that switches between Custom Tailoring and the manual compiler ---- */
      function CompilerHub() {
        var m = useState("tailor");
        var mode = m[0],
          setMode = m[1];
        return (
          <div className="page">
            <div className="wrap">
              <SecHead
                eyebrow="Admin Tool"
                title="Compile a Résumé"
                lead="Tailor an application to one posting, or build a résumé by hand from your saved sections."
              />
              <div className="mode-switch">
                <div
                  className={"mode-btn" + (mode === "tailor" ? " on" : "")}
                  role="button"
                  tabIndex={0}
                  onClick={function () {
                    setMode("tailor");
                  }}
                  onKeyDown={kb(function () {
                    setMode("tailor");
                  })}
                >
                  ✦ Custom Tailoring
                </div>
                <div
                  className={"mode-btn" + (mode === "manual" ? " on" : "")}
                  role="button"
                  tabIndex={0}
                  onClick={function () {
                    setMode("manual");
                  }}
                  onKeyDown={kb(function () {
                    setMode("manual");
                  })}
                >
                  Manual Compiler
                </div>
              </div>
              {mode === "tailor" ? (
                <div className="comp-card">
                  <div className="modal-body">
                    <CustomTailor />
                  </div>
                </div>
              ) : (
                <ResumeCompiler embedded={true} />
              )}
            </div>
          </div>
        );
      }

      function ResumeCompiler(props) {
        var embedded = props && props.embedded;
        const isAdmin = true;
        const [order, setOrder] = useState(["cover", "resume", "docs", "refs"]);
        const [on, setOn] = useState({
          cover: false,
          resume: true,
          docs: false,
          refs: false,
        });
        const [compiling, setCompiling] = useState(false);

        // cover
        const [cover, setCover] = useState({
          company: "",
          position: "",
          body: "",
        });
        const [drafting, setDrafting] = useState(false);
        // resume
        const [style, setStyle] = useState("Classic");
        const [picked, setPicked] = useState(
          EXPERIENCE.filter((e) => e.type !== "sports").map((e) => e.id),
        );
        const [tagFilter, setTagFilter] = useState([]);
        // docs
        const [docSel, setDocSel] = useState([]);
        // refs
        const poolActive = REF_POOL.filter((r) => r.active);
        const [refs, setRefs] = useState(
          isAdmin
            ? poolActive.map((r) => ({
                name: r.name,
                detail: r.title,
                rel: r.rel,
                phone: r.phone,
                email: r.email,
                save: false,
              }))
            : [
                {
                  name: "",
                  detail: "",
                  rel: "",
                  phone: "",
                  email: "",
                  save: false,
                },
              ],
        );

        const move = (idx, dir) => {
          const j = idx + dir;
          if (j < 0 || j >= order.length) return;
          const a = [...order];
          const tmp = a[idx];
          a[idx] = a[j];
          a[j] = tmp;
          setOrder(a);
        };

        const toggleTag = (t) =>
          setTagFilter((a) =>
            a.includes(t) ? a.filter((x) => x !== t) : [...a, t],
          );
        const visibleRoles =
          tagFilter.length === 0
            ? EXPERIENCE
            : EXPERIENCE.filter((e) =>
                e.tags.some((t) => tagFilter.includes(t)),
              );
        const togglePick = (id) =>
          setPicked((p) =>
            p.includes(id) ? p.filter((x) => x !== id) : [...p, id],
          );
        const toggleDoc = (f) =>
          setDocSel((s) =>
            s.includes(f) ? s.filter((x) => x !== f) : [...s, f],
          );

        const docList = sortCerts(CERTS.filter((c) => c.file));

        const draftCover = () => {
          setDrafting(true);
          setTimeout(() => {
            const co = cover.company || "your organization",
              pos = cover.position || "this position";
            const body = `Dear Hiring Team,\n\nI am writing to express my strong interest in the ${pos} role at ${co}. After nearly twelve years of leadership in the United States Navy and a career since in customer success and program management, I have built a track record of leading teams, managing complex operations, and delivering measurable results in demanding environments.\n\nMy background spans security operations, training program management, and enterprise customer success, always anchored in clear communication, accountability, and a bias toward getting things done. I am confident that the same discipline and adaptability that defined my military service and my work today would allow me to contribute quickly and meaningfully to ${co}.\n\nI would welcome the opportunity to discuss how my experience aligns with your needs. Thank you for your time and consideration.`;
            setCover((c) => ({ ...c, body }));
            setDrafting(false);
          }, 1400); // Production: POST to Cloudflare Worker → Claude API
        };

        const addRef = () =>
          refs.length < 5 &&
          setRefs([
            ...refs,
            {
              name: "",
              detail: "",
              rel: "",
              phone: "",
              email: "",
              save: false,
            },
          ]);
        const setRef = (i, k, val) =>
          setRefs(refs.map((r, j) => (j === i ? { ...r, [k]: val } : r)));
        const delRef = (i) => setRefs(refs.filter((_, j) => j !== i));

        const anyOn = Object.values(on).some(Boolean);

        const compile = async () => {
          if (!anyOn) {
            alert("Select at least one section to include.");
            return;
          }
          setCompiling(true);
          try {
            await buildPDF();
          } catch (err) {
            console.error(err);
            alert("Something went wrong building the PDF: " + err.message);
          }
          setCompiling(false);
        };

        async function buildPDF() {
          const { jsPDF } = window.jspdf;
          const doc = new jsPDF({ unit: "pt", format: "letter" });
          const W = 612,
            M = 54;
          let first = true;
          const foot = () => {
            doc.setFont("helvetica", "italic");
            doc.setFontSize(8);
            doc.setTextColor(150, 150, 150);
            doc.text(SITE.pdfFooter, W / 2, 760, { align: "center" });
          };
          const header = (subtitle) => {
            doc.setFont("helvetica", "bold");
            doc.setFontSize(24);
            doc.setTextColor(13, 27, 42);
            doc.text("Dustin Burich", M, 64);
            doc.setDrawColor(201, 168, 76);
            doc.setLineWidth(2);
            doc.line(M, 74, W - M, 74);
            doc.setFont("helvetica", "normal");
            doc.setFontSize(9);
            doc.setTextColor(90, 90, 90);
            doc.text(
              `${phoneText}   •   ${SITE.email}   •   ${SITE.location}`,
              M,
              90,
            );
            if (subtitle) {
              doc.setFont("helvetica", "bold");
              doc.setFontSize(11);
              doc.setTextColor(14, 116, 144);
              doc.text(subtitle, M, 108);
            }
            return subtitle ? 128 : 112;
          };
          const newPage = () => {
            if (!first) {
              doc.addPage();
            }
            first = false;
          };

          for (const sec of order) {
            if (!on[sec]) continue;

            if (sec === "cover") {
              newPage();
              let y = header(null);
              doc.setFont("helvetica", "normal");
              doc.setFontSize(10);
              doc.setTextColor(40, 40, 40);
              y += 6;
              const date = new Date().toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
              });
              doc.text(date, M, y);
              y += 22;
              if (cover.company) {
                doc.setFont("helvetica", "bold");
                doc.text(cover.company, M, y);
                y += 15;
                doc.setFont("helvetica", "normal");
              }
              if (cover.position) {
                doc.text("Re: " + cover.position, M, y);
                y += 20;
              }
              const body =
                cover.body ||
                "Dear Hiring Team,\n\n[Your cover letter body goes here.]";
              const lines = doc.splitTextToSize(body, W - M * 2);
              doc.setFontSize(10.5);
              lines.forEach((ln) => {
                if (y > 710) {
                  foot();
                  doc.addPage();
                  y = 64;
                }
                doc.text(ln, M, y);
                y += 15.5;
              });
              y += 10;
              doc.text("Respectfully,", M, y);
              y += 34;
              // Production: doc.addImage(signaturePng,...) here
              doc.setFont("helvetica", "bold");
              doc.setFontSize(12);
              doc.setTextColor(13, 27, 42);
              doc.text("Dustin Burich", M, y);
              foot();
            }

            if (sec === "resume") {
              newPage();
              const modern = style === "Modern";
              let y = header(modern ? "Professional Résumé" : null);
              const DISP = [
                "c1",
                "e6",
                "e5",
                "e4",
                "e3",
                "e2",
                "e1",
                "e0",
                "s1",
                "s2",
                "s3",
              ];
              const roles = EXPERIENCE.filter((e) =>
                picked.includes(e.id),
              ).sort((a, b) => DISP.indexOf(a.id) - DISP.indexOf(b.id));
              const drawSection = (label) => {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(12);
                doc.setTextColor(14, 116, 144);
                doc.text(label.toUpperCase(), M, y);
                if (modern) {
                  doc.setDrawColor(14, 116, 144);
                } else {
                  doc.setDrawColor(180, 180, 180);
                }
                doc.setLineWidth(modern ? 1.4 : 0.6);
                doc.line(M, y + 5, W - M, y + 5);
                y += 20;
              };
              drawSection("Professional Experience");
              roles.forEach((r) => {
                if (y > 700) {
                  foot();
                  doc.addPage();
                  y = 64;
                }
                doc.setFont("helvetica", "bold");
                doc.setFontSize(11);
                doc.setTextColor(13, 27, 42);
                doc.text(r.title, M, y);
                doc.setFont("helvetica", "normal");
                doc.setFontSize(9);
                doc.setTextColor(120, 120, 120);
                doc.text(r.dates, W - M, y, { align: "right" });
                y += 13;
                doc.setFont("helvetica", "bold");
                doc.setFontSize(9.5);
                doc.setTextColor(14, 116, 144);
                doc.text(r.org + "  ·  " + r.loc, M, y);
                y += 13;
                doc.setFont("helvetica", "normal");
                doc.setFontSize(9.5);
                doc.setTextColor(50, 50, 50);
                r.bullets.forEach((b) => {
                  const ls = doc.splitTextToSize("•  " + b, W - M * 2 - 6);
                  ls.forEach((ln) => {
                    if (y > 720) {
                      foot();
                      doc.addPage();
                      y = 64;
                    }
                    doc.text(ln, M + 4, y);
                    y += 12.5;
                  });
                });
                y += 10;
              });
              foot();
            }

            if (sec === "docs") {
              // handled after jsPDF via pdf-lib merge — mark selection; here we add an index page
              newPage();
              let y = header("Supporting Documents");
              doc.setFont("helvetica", "normal");
              doc.setFontSize(10);
              doc.setTextColor(50, 50, 50);
              doc.text(
                "The following documents are attached in the order selected:",
                M,
                y,
              );
              y += 22;
              docSel.forEach((f, i) => {
                const c = docList.find((d) => d.file === f);
                doc.setFont("helvetica", "bold");
                doc.setFontSize(10.5);
                doc.setTextColor(13, 27, 42);
                doc.text(`${i + 1}.  ${c ? c.t : f}`, M, y);
                y += 14;
                doc.setFont("helvetica", "normal");
                doc.setFontSize(9);
                doc.setTextColor(120, 120, 120);
                if (c) {
                  doc.text("     " + c.iss, M, y);
                  y += 18;
                }
              });
              foot();
            }

            if (sec === "refs") {
              newPage();
              let y = header("References");
              const valid = refs.filter((r) => r.name.trim());
              valid.forEach((r) => {
                if (y > 680) {
                  foot();
                  doc.addPage();
                  y = 64;
                }
                // card
                doc.setDrawColor(210, 210, 210);
                doc.setLineWidth(0.8);
                doc.roundedRect(M, y - 14, W - M * 2, 64, 6, 6, "S");
                doc.setFont("helvetica", "bold");
                doc.setFontSize(12);
                doc.setTextColor(13, 27, 42);
                doc.text(r.name, M + 14, y + 4);
                doc.setFont("helvetica", "normal");
                doc.setFontSize(9.5);
                doc.setTextColor(14, 116, 144);
                if (r.detail) {
                  doc.text(r.detail, M + 14, y + 18);
                }
                doc.setTextColor(90, 90, 90);
                doc.setFontSize(9);
                const contact = [r.phone, r.email]
                  .filter(Boolean)
                  .join("   ·   ");
                if (contact) {
                  doc.text(contact, M + 14, y + 32);
                }
                if (r.rel) {
                  doc.setFont("helvetica", "italic");
                  doc.text(
                    doc.splitTextToSize(r.rel, W - M * 2 - 28),
                    M + 14,
                    y + 44,
                  );
                }
                y += 80;
              });
              if (valid.length === 0) {
                doc.setFont("helvetica", "italic");
                doc.setFontSize(10);
                doc.setTextColor(120, 120, 120);
                doc.text("No references entered.", M, y);
              }
              foot();
            }
          }

          // ── Merge supporting-document PDFs with pdf-lib (fetch → fallback placeholder) ──
          let finalBytes;
          if (on.docs && docSel.length > 0) {
            const { PDFDocument } = PDFLib;
            const genBytes = doc.output("arraybuffer");
            const outPdf = await PDFDocument.load(genBytes);
            for (const f of docSel) {
              let merged = false;
              try {
                const res = await fetch("/assets/certs/" + f); // Production path
                if (res.ok) {
                  const buf = await res.arrayBuffer();
                  const src = await PDFDocument.load(buf);
                  const pages = await outPdf.copyPages(
                    src,
                    src.getPageIndices(),
                  );
                  pages.forEach((p) => outPdf.addPage(p));
                  merged = true;
                }
              } catch (e) {
                /* sandbox: no file → fallback */
              }
              if (!merged) {
                const c = docList.find((d) => d.file === f);
                const pg = outPdf.addPage([612, 792]);
                pg.drawText("Supporting Document", { x: 54, y: 720, size: 20 });
                pg.drawText(c ? c.t : f, { x: 54, y: 686, size: 13 });
                if (c) pg.drawText(c.iss, { x: 54, y: 666, size: 10 });
                pg.drawText(
                  "[ In production, the scanned PDF pages for this document",
                  { x: 54, y: 120, size: 10 },
                );
                pg.drawText("  are merged here automatically. ]", {
                  x: 54,
                  y: 104,
                  size: 10,
                });
              }
            }
            finalBytes = await outPdf.save();
          } else {
            finalBytes = doc.output("arraybuffer");
          }

          // download (robust: fixed revoke timing + sandbox fallback)
          const co =
            cover.company && on.cover
              ? "_" + cover.company.replace(/[^a-z0-9]/gi, "")
              : "";
          downloadBytes(finalBytes, `Dustin_Burich_Resume${co}.pdf`);
        }

        var inner = (
          <React.Fragment>
            {compiling && <Spinner label="Compiling Résumé" />}
            {!embedded && (
              <SecHead
                eyebrow="Admin Tool"
                title="Résumé Compiler"
                lead="Flip on the sections you want, reorder them with the arrows, then compile one clean PDF."
              />
            )}
            <div className="comp-card">
              <div className="modal-body">
                {(() => {
                  const eo = order.filter((k) => on[k]);
                  return eo.length > 0 ? (
                    <div className="assembly">
                      <span className="asm-lbl">Your PDF</span>
                      {eo.map((k, i) => (
                        <React.Fragment key={k}>
                          {i > 0 && <span className="arrow">→</span>}
                          <span className="achip">
                            <span className="anum">{i + 1}</span>
                            {SECTION_DEFS.find((s) => s.key === k).t}
                          </span>
                        </React.Fragment>
                      ))}
                    </div>
                  ) : (
                    <div className="assembly empty-asm">
                      Turn on a section below to start building your résumé.
                    </div>
                  );
                })()}
                {order.map((key, idx) => {
                  const def = SECTION_DEFS.find((s) => s.key === key);
                  const isOn = on[key];
                  return (
                    <div className={"csec" + (isOn ? " active" : "")} key={key}>
                      <div className="csec-head">
                        <div className={"csec-num" + (isOn ? "" : " off")}>
                          {isOn
                            ? order.slice(0, idx + 1).filter((k) => on[k])
                                .length
                            : "–"}
                        </div>
                        <div className="csec-title">
                          <div className="t">{def.t}</div>
                          <div className="d">{def.d}</div>
                        </div>
                        {isOn && (
                          <div className="csec-ord">
                            <button
                              className="ordbtn"
                              disabled={idx === 0}
                              onClick={() => move(idx, -1)}
                              title="Move up"
                            >
                              ▲
                            </button>
                            <button
                              className="ordbtn"
                              disabled={idx === order.length - 1}
                              onClick={() => move(idx, 1)}
                              title="Move down"
                            >
                              ▼
                            </button>
                          </div>
                        )}
                        <div
                          className={"tsw" + (isOn ? " on" : "")}
                          onClick={() => setOn({ ...on, [key]: !isOn })}
                        />
                      </div>
                      {isOn && (
                        <div className="cbody">
                          <div className="cbody-in">
                            {key === "cover" && (
                              <div>
                                <div className="field">
                                  <label>Company</label>
                                  <input
                                    value={cover.company}
                                    onChange={(e) =>
                                      setCover({
                                        ...cover,
                                        company: e.target.value,
                                      })
                                    }
                                    placeholder="e.g. Trego-Dugan Aviation"
                                  />
                                </div>
                                <div className="field">
                                  <label>Position</label>
                                  <input
                                    value={cover.position}
                                    onChange={(e) =>
                                      setCover({
                                        ...cover,
                                        position: e.target.value,
                                      })
                                    }
                                    placeholder="e.g. General Manager"
                                  />
                                </div>
                                <div className="field">
                                  <label>Body</label>
                                  <textarea
                                    value={cover.body}
                                    onChange={(e) =>
                                      setCover({
                                        ...cover,
                                        body: e.target.value,
                                      })
                                    }
                                    placeholder="Write your cover letter, or use the draft helper below."
                                  />
                                </div>
                                <button
                                  className="btn btn-ghost btn-sm"
                                  onClick={draftCover}
                                  disabled={drafting}
                                >
                                  {drafting
                                    ? "Drafting…"
                                    : "✦ Help me draft this"}
                                </button>
                                <div
                                  style={{
                                    fontSize: 11.5,
                                    color: "var(--mist)",
                                    opacity: 0.55,
                                    marginTop: 8,
                                  }}
                                >
                                  Sandbox uses a local template. In production
                                  this calls Claude via your Cloudflare Worker.
                                  Your signature is placed above your name
                                  automatically.
                                </div>
                              </div>
                            )}
                            {key === "resume" && (
                              <div>
                                <div className="style-toggle">
                                  {["Classic", "Modern"].map((s) => (
                                    <div
                                      key={s}
                                      className={
                                        "style-opt" + (style === s ? " on" : "")
                                      }
                                      onClick={() => setStyle(s)}
                                    >
                                      {s}
                                    </div>
                                  ))}
                                </div>
                                {isAdmin && (
                                  <div style={{ marginBottom: 12 }}>
                                    <div
                                      className="ref-mini"
                                      style={{ marginBottom: 6 }}
                                    >
                                      Filter roles by tag (admin)
                                    </div>
                                    <div className="chips">
                                      {TAGS.map((t) => (
                                        <span
                                          key={t}
                                          className={
                                            "chip" +
                                            (tagFilter.includes(t) ? " on" : "")
                                          }
                                          onClick={() => toggleTag(t)}
                                          style={{
                                            fontSize: 11.5,
                                            padding: "4px 10px",
                                          }}
                                        >
                                          {t}
                                        </span>
                                      ))}
                                    </div>
                                  </div>
                                )}
                                <div
                                  className="ref-mini"
                                  style={{ marginBottom: 6 }}
                                >
                                  Select roles to include
                                </div>
                                <div className="li-pick">
                                  {visibleRoles.map((e) => (
                                    <div
                                      className="li-row"
                                      key={e.id}
                                      onClick={() => togglePick(e.id)}
                                    >
                                      <div
                                        className={
                                          "li-cbox" +
                                          (picked.includes(e.id) ? " on" : "")
                                        }
                                      />
                                      <div className="li-txt">
                                        <div className="lt">{e.title}</div>
                                        <div className="lo">
                                          {e.org} · {e.dates}
                                        </div>
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}
                            {key === "docs" && (
                              <div>
                                <div
                                  className="ref-mini"
                                  style={{ marginBottom: 6 }}
                                >
                                  Select documents to attach ({docSel.length}{" "}
                                  selected)
                                </div>
                                <div className="li-pick">
                                  {docList.map((c) => (
                                    <div
                                      className="li-row"
                                      key={c.file}
                                      onClick={() => toggleDoc(c.file)}
                                    >
                                      <div
                                        className={
                                          "li-cbox" +
                                          (docSel.includes(c.file) ? " on" : "")
                                        }
                                      />
                                      <div className="li-txt">
                                        <div className="lt">{c.t}</div>
                                        <div className="lo">{c.iss}</div>
                                      </div>
                                    </div>
                                  ))}
                                </div>
                                {docSel.length > 0 && (
                                  <div
                                    style={{
                                      fontSize: 11.5,
                                      color: "var(--sea)",
                                      marginTop: 8,
                                    }}
                                  >
                                    Attached in the order selected above.
                                    Drag-reordering of documents ships in the
                                    production build.
                                  </div>
                                )}
                              </div>
                            )}
                            {key === "refs" && (
                              <div>
                                {isAdmin && (
                                  <div
                                    style={{
                                      fontSize: 11.5,
                                      color: "var(--gold)",
                                      marginBottom: 10,
                                    }}
                                  >
                                    Pulled from your {poolActive.length} active
                                    saved references. Edit or add below (max 5
                                    in a resume).
                                  </div>
                                )}
                                {refs.map((r, i) => (
                                  <div className="ref-card" key={i}>
                                    <div className="ref-grid">
                                      <div className="full">
                                        <div className="ref-mini">
                                          Name (required)
                                        </div>
                                        <input
                                          className="ref-in"
                                          value={r.name}
                                          onChange={(e) =>
                                            setRef(i, "name", e.target.value)
                                          }
                                          placeholder="Full name"
                                        />
                                      </div>
                                      <div className="full">
                                        <div className="ref-mini">
                                          Title / Organization
                                        </div>
                                        <input
                                          className="ref-in"
                                          value={r.detail}
                                          onChange={(e) =>
                                            setRef(i, "detail", e.target.value)
                                          }
                                          placeholder="Role, organization"
                                        />
                                      </div>
                                      <div>
                                        <div className="ref-mini">Phone</div>
                                        <input
                                          className="ref-in"
                                          value={r.phone}
                                          onChange={(e) =>
                                            setRef(i, "phone", e.target.value)
                                          }
                                          placeholder="Optional"
                                        />
                                      </div>
                                      <div>
                                        <div className="ref-mini">Email</div>
                                        <input
                                          className="ref-in"
                                          value={r.email}
                                          onChange={(e) =>
                                            setRef(i, "email", e.target.value)
                                          }
                                          placeholder="Optional"
                                        />
                                      </div>
                                      <div className="full">
                                        <div className="ref-mini">
                                          How you know them
                                        </div>
                                        <input
                                          className="ref-in"
                                          value={r.rel}
                                          onChange={(e) =>
                                            setRef(i, "rel", e.target.value)
                                          }
                                          placeholder="Short note"
                                        />
                                      </div>
                                    </div>
                                    <div
                                      style={{
                                        display: "flex",
                                        justifyContent: "space-between",
                                        alignItems: "center",
                                        marginTop: 10,
                                      }}
                                    >
                                      <div
                                        className="ref-save"
                                        onClick={() =>
                                          setRef(i, "save", !r.save)
                                        }
                                      >
                                        <div
                                          className={
                                            "li-cbox" + (r.save ? " on" : "")
                                          }
                                        />{" "}
                                        Save this reference for later
                                      </div>
                                      {refs.length > 1 && (
                                        <button
                                          className="ref-del"
                                          onClick={() => delRef(i)}
                                        >
                                          Remove
                                        </button>
                                      )}
                                    </div>
                                  </div>
                                ))}
                                {refs.length < 5 && (
                                  <button className="add-ref" onClick={addRef}>
                                    + Add Reference
                                  </button>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
              <div className="modal-foot">
                <div
                  style={{ fontSize: 12.5, color: "var(--mist)", opacity: 0.6 }}
                >
                  {Object.values(on).filter(Boolean).length} section
                  {Object.values(on).filter(Boolean).length !== 1 ? "s" : ""} ·
                  reorder with ▲▼
                </div>
                <button className="btn btn-gold" onClick={compile}>
                  Compile PDF ↓
                </button>
              </div>
            </div>
          </React.Fragment>
        );
        return embedded ? (
          inner
        ) : (
          <div className="page">
            <div className="wrap">{inner}</div>
          </div>
        );
      }

      /* ============================================================
   COMPILE PAGE (password-gated)
============================================================ */
      function CompilePage({ isAdmin, onUnlock }) {
        const [v, setV] = useState("");
        const [shake, setShake] = useState(false);
        const submit = () => {
          if (v.trim().toLowerCase() === SITE.adminKey.toLowerCase()) {
            onUnlock();
          } else {
            setShake(true);
            setV("");
            setTimeout(() => setShake(false), 400);
          }
        };
        if (isAdmin) return <CompilerHub />;
        return (
          <div className="page">
            <div className="wrap">
              <div className="lock-card">
                <svg
                  className="lk-ico"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                >
                  <rect x="4" y="11" width="16" height="10" rx="2" />
                  <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                </svg>
                <h2>Résumé Compiler</h2>
                <p>
                  This tool is password protected. Enter the access key to build
                  and download a tailored résumé, cover letter, and reference
                  package.
                </p>
                <input
                  className={"key-in" + (shake ? " shake" : "")}
                  value={v}
                  autoFocus
                  onChange={(e) => setV(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && submit()}
                  placeholder="•••••"
                />
                <button className="btn btn-gold" onClick={submit}>
                  Unlock
                </button>
              </div>
            </div>
          </div>
        );
      }

      /* ============================================================
   ROOT APP
============================================================ */
      /* ============================================================
   FILE ACCESS + VIEWER HELPERS (added)
============================================================ */

      /* ---- auto-fit the viewer title to one line, two only if needed ---- */
      function FitTitle(props) {
        var ref = useRef(null);
        React.useLayoutEffect(
          function () {
            var el = ref.current;
            if (!el) {
              return;
            }
            var MAX = 17,
              MIN = 12.5;
            var fit = function () {
              el.style.whiteSpace = "nowrap";
              el.style.fontSize = MAX + "px";
              var fs = MAX,
                guard = 0;
              while (
                fs > MIN &&
                el.scrollWidth > el.clientWidth + 1 &&
                guard < 40
              ) {
                fs -= 0.5;
                el.style.fontSize = fs + "px";
                guard++;
              }
              el.style.whiteSpace =
                el.scrollWidth > el.clientWidth + 1 ? "normal" : "nowrap";
            };
            fit();
            window.addEventListener("resize", fit);
            return function () {
              window.removeEventListener("resize", fit);
            };
          },
          [props.text],
        );
        return (
          <span ref={ref} className="cv-title cv-title-fit">
            {props.text}
          </span>
        );
      }

      /* ---- get natural size of a data-URI image ---- */
      function imgSize(src) {
        return new Promise(function (resolve) {
          var im = new Image();
          im.onload = function () {
            resolve({ w: im.naturalWidth || 665, h: im.naturalHeight || 860 });
          };
          im.onerror = function () {
            resolve({ w: 665, h: 860 });
          };
          im.src = src;
        });
      }

      /* ---- download a document as PDF: real asset on deploy, embedded images in preview ---- */
      async function downloadCertPDF(file, title) {
        var name = (title ? title : file)
          .replace(/[^\w.-]+/g, "_")
          .replace(/_+/g, "_");
        if (!/\.pdf$/i.test(name)) {
          name = name + ".pdf";
        }
        // 1) try the full-resolution asset (present on the deployed site)
        try {
          var res = await fetch("assets/certs/" + file, { cache: "no-store" });
          if (res && res.ok) {
            var buf = await res.arrayBuffer();
            var head = new Uint8Array(buf.slice(0, 5));
            if (
              head[0] === 37 &&
              head[1] === 80 &&
              head[2] === 68 &&
              head[3] === 70
            ) {
              downloadBytes(buf, file);
              return;
            }
          }
        } catch (e) {
          /* fall back to embedded images */
        }
        // 2) rebuild from the embedded page images
        var pages =
          window.CERT_IMAGES && window.CERT_IMAGES[file]
            ? window.CERT_IMAGES[file]
            : [];
        if (!pages.length) {
          throw new Error("This document isn't bundled in the preview.");
        }
        var jsPDF = window.jspdf.jsPDF;
        var doc = null;
        for (var i = 0; i < pages.length; i++) {
          var dim = await imgSize(pages[i]);
          var orient = dim.w >= dim.h ? "landscape" : "portrait";
          if (i === 0) {
            doc = new jsPDF({
              unit: "pt",
              format: "letter",
              orientation: orient,
            });
          } else {
            doc.addPage("letter", orient);
          }
          var pw = doc.internal.pageSize.getWidth(),
            ph = doc.internal.pageSize.getHeight();
          var scale = Math.min((pw - 24) / dim.w, (ph - 24) / dim.h);
          var w = dim.w * scale,
            h = dim.h * scale;
          doc.addImage(pages[i], "JPEG", (pw - w) / 2, (ph - h) / 2, w, h);
        }
        downloadBytes(doc.output("arraybuffer"), name);
      }

      /* ---- one downloadable document row ---- */
      function FileRow(props) {
        var s = useState("idle");
        var st = s[0],
          setSt = s[1];
        var dl = async function () {
          setSt("working");
          try {
            await downloadCertPDF(props.file, props.title);
          } catch (e) {
            alert("Could not prepare that file: " + (e.message || e));
          }
          setSt("idle");
        };
        return (
          <div className="file-row">
            <div className="file-info">
              <div className="file-title">{props.title}</div>
              {props.meta && <div className="file-meta">{props.meta}</div>}
            </div>
            <button
              className="btn btn-blue btn-sm"
              onClick={dl}
              disabled={st === "working"}
            >
              {st === "working" ? "Preparing…" : "Open PDF ↗"}
            </button>
          </div>
        );
      }

      function FileGroup(props) {
        if (!props.docs.length) {
          return null;
        }
        return (
          <div className="file-group">
            <div className="file-group-h">
              {props.title}{" "}
              <span className="file-count">{props.docs.length}</span>
            </div>
            {props.docs.map(function (d, i) {
              return (
                <FileRow
                  key={d.file || i}
                  file={d.file}
                  title={d.title}
                  meta={d.meta}
                />
              );
            })}
          </div>
        );
      }

      /* ---- cloud vault: upload + fetch personal documents via the Worker (R2) ---- */
      function fmtSize(n) {
        if (n === null || n === undefined || isNaN(n)) {
          return "";
        }
        if (n < 1024) {
          return n + " B";
        }
        if (n < 1048576) {
          return Math.round(n / 1024) + " KB";
        }
        return (n / 1048576).toFixed(1) + " MB";
      }

      function CloudFiles() {
        const base = (SITE.workerUrl || "").replace(/\/+$/, "");
        const [vkey, setVkey] = useState("");
        const [entered, setEntered] = useState("");
        const [files, setFiles] = useState(null);
        const [busy, setBusy] = useState("");
        const [err, setErr] = useState("");
        const [drag, setDrag] = useState(false);
        const inRef = useRef(null);

        const call = async (path, opts) => {
          const o = opts || {};
          o.headers = Object.assign({ "x-files-key": vkey }, o.headers || {});
          const res = await fetch(base + path, o);
          if (res.status === 401) {
            throw new Error("Wrong vault key.");
          }
          if (!res.ok) {
            let msg = "Request failed (" + res.status + ")";
            try {
              const j = await res.json();
              if (j && j.error) {
                msg = j.error;
              }
            } catch (e) {}
            throw new Error(msg);
          }
          return res;
        };

        const refresh = async (k) => {
          const res = await fetch(base + "/files", {
            headers: { "x-files-key": k },
          });
          if (res.status === 401) {
            throw new Error("Wrong vault key.");
          }
          if (!res.ok) {
            throw new Error("Could not reach the vault (" + res.status + ").");
          }
          const j = await res.json();
          setFiles(j.files || []);
        };

        const connect = async () => {
          const k = entered.trim();
          if (!k) {
            return;
          }
          setBusy("connect");
          setErr("");
          try {
            await refresh(k);
            setVkey(k);
          } catch (e) {
            setErr(e.message || String(e));
          }
          setBusy("");
        };

        const upload = async (list) => {
          const arr = Array.from(list || []);
          if (!arr.length) {
            return;
          }
          setBusy("upload");
          setErr("");
          try {
            for (let i = 0; i < arr.length; i++) {
              const f = arr[i];
              if (f.size > 25 * 1024 * 1024) {
                throw new Error(f.name + " is over the 25 MB limit.");
              }
              await call("/files/" + encodeURIComponent(f.name), {
                method: "POST",
                body: f,
                headers: {
                  "Content-Type": f.type || "application/octet-stream",
                },
              });
            }
            await refresh(vkey);
          } catch (e) {
            setErr(e.message || String(e));
          }
          setBusy("");
        };

        const download = async (name) => {
          setBusy("dl:" + name);
          setErr("");
          try {
            const res = await call("/files/" + encodeURIComponent(name));
            const buf = await res.arrayBuffer();
            downloadBytes(buf, name);
          } catch (e) {
            setErr(e.message || String(e));
          }
          setBusy("");
        };

        const remove = async (name) => {
          if (
            !window.confirm(
              'Remove "' + name + "\" from the vault? This can't be undone.",
            )
          ) {
            return;
          }
          setBusy("rm:" + name);
          setErr("");
          try {
            await call("/files/" + encodeURIComponent(name), {
              method: "DELETE",
            });
            await refresh(vkey);
          } catch (e) {
            setErr(e.message || String(e));
          }
          setBusy("");
        };

        if (!base) {
          return (
            <div className="file-group">
              <div className="file-group-h">
                Cloud Vault <span className="file-count">off</span>
              </div>
              <div className="files-note" style={{ margin: "0 0 8px" }}>
                Uploads switch on once your Cloudflare Worker is deployed with
                the R2 bucket (WORKER.md, step "File vault"). Then this section
                lets you add certificates and letters from any device, no code
                edits, and download them anywhere. The bundled documents below
                are always available.
              </div>
            </div>
          );
        }

        if (!vkey) {
          return (
            <div className="file-group">
              <div className="file-group-h">
                Cloud Vault <span className="file-count">locked</span>
              </div>
              <div className="file-row">
                <div className="file-info" style={{ flex: 1 }}>
                  <div className="file-title">
                    Enter your vault key to open cloud storage
                  </div>
                  <div className="file-meta">
                    This is the FILES_KEY secret on your Worker, separate from
                    the site key.
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <input
                    className="key-in"
                    style={{ margin: 0, width: 150 }}
                    type="password"
                    value={entered}
                    placeholder="vault key"
                    onChange={(e) => setEntered(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        connect();
                      }
                    }}
                  />
                  <button
                    className="btn btn-gold btn-sm"
                    onClick={connect}
                    disabled={busy === "connect"}
                  >
                    {busy === "connect" ? "Checking…" : "Open"}
                  </button>
                </div>
              </div>
              {err && <div className="file-err">{err}</div>}
            </div>
          );
        }

        return (
          <div className="file-group">
            <div className="file-group-h">
              Cloud Vault{" "}
              <span className="file-count">{files ? files.length : 0}</span>
            </div>
            <div
              className={"dropzone" + (drag ? " drag" : "")}
              onDragOver={(e) => {
                e.preventDefault();
                setDrag(true);
              }}
              onDragLeave={() => setDrag(false)}
              onDrop={(e) => {
                e.preventDefault();
                setDrag(false);
                upload(e.dataTransfer.files);
              }}
              onClick={() => {
                if (inRef.current) {
                  inRef.current.click();
                }
              }}
            >
              <input
                ref={inRef}
                type="file"
                multiple
                style={{ display: "none" }}
                onChange={(e) => {
                  upload(e.target.files);
                  e.target.value = "";
                }}
              />
              {busy === "upload"
                ? "Uploading…"
                : "Drop files here, or tap to choose (PDF, images, anything · 25 MB max each)"}
            </div>
            {err && <div className="file-err">{err}</div>}
            {files && files.length === 0 && (
              <div className="file-meta" style={{ padding: "6px 2px" }}>
                Nothing in the vault yet. Anything you add is downloadable from
                any device with the key.
              </div>
            )}
            {(files || []).map((f) => (
              <div className="file-row" key={f.name}>
                <div className="file-info">
                  <div className="file-title">{f.name}</div>
                  <div className="file-meta">
                    {fmtSize(f.size)}
                    {f.uploaded ? " · " + f.uploaded.slice(0, 10) : ""}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8, flex: "0 0 auto" }}>
                  <button
                    className="btn btn-blue btn-sm"
                    onClick={() => download(f.name)}
                    disabled={busy === "dl:" + f.name}
                  >
                    {busy === "dl:" + f.name ? "…" : "Open PDF ↗"}
                  </button>
                  <button
                    className="btn btn-ghost btn-sm"
                    onClick={() => remove(f.name)}
                    disabled={busy === "rm:" + f.name}
                  >
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        );
      }

      /* ---- the Access Files tab (admin-gated) ---- */
      function FilesPage(props) {
        var isAdmin = props.isAdmin,
          onUnlock = props.onUnlock;
        var v = useState("");
        var val = v[0],
          setVal = v[1];
        var k = useState(false);
        var shake = k[0],
          setShake = k[1];
        var submit = function () {
          if (val.trim().toLowerCase() === SITE.adminKey.toLowerCase()) {
            onUnlock();
          } else {
            setShake(true);
            setVal("");
            setTimeout(function () {
              setShake(false);
            }, 400);
          }
        };
        if (!isAdmin) {
          return (
            <div className="page">
              <div className="wrap">
                <div className="lock-card">
                  <svg
                    className="lk-ico"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.5"
                  >
                    <rect x="4" y="11" width="16" height="10" rx="2" />
                    <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                  </svg>
                  <h2>Access Files</h2>
                  <p>
                    This is a private area for downloading your certificates,
                    letters, and transcripts. Enter the access key to continue.
                  </p>
                  <input
                    className={"key-in" + (shake ? " shake" : "")}
                    value={val}
                    autoFocus
                    onChange={function (e) {
                      setVal(e.target.value);
                    }}
                    onKeyDown={function (e) {
                      if (e.key === "Enter") {
                        submit();
                      }
                    }}
                    placeholder="•••••"
                  />
                  <button className="btn btn-gold" onClick={submit}>
                    Unlock
                  </button>
                </div>
              </div>
            </div>
          );
        }
        var certDocs = sortDocumentsNewestFirst(
          CERTS.filter(function (c) {
            return c.file;
          }),
        ).map(function (c) {
          return { file: c.file, title: c.t, meta: c.iss };
        });
        var eduList = [];
        sortDocumentsNewestFirst(EDU_DEGREES).forEach(function (d) {
          if (d.file) {
            eduList.push({ file: d.file, title: d.ti, meta: d.meta });
          }
        });
        if (EDU_JST && EDU_JST.file) {
          eduList.push({
            file: EDU_JST.file,
            title: EDU_JST.ti,
            meta: EDU_JST.meta,
          });
        }
        sortDocumentsNewestFirst(APPRENTICE).forEach(function (a) {
          if (a.file) {
            eduList.push({ file: a.file, title: a.ti, meta: a.meta });
          }
        });
        eduList = sortDocumentsNewestFirst(
          eduList.map(function (item) {
            return {
              ti: item.title,
              meta: item.meta,
              file: item.file,
            };
          }),
        ).map(function (item) {
          return {
            file: item.file,
            title: item.ti,
            meta: item.meta,
          };
        });
        return (
          <div className="page">
            <div className="wrap">
              <SecHead
                eyebrow="Admin Tool"
                title="Access Files"
                lead="Download any of your certificates, letters, and transcripts as a PDF, straight from your site, whenever you need a copy on the go."
              />
              <CloudFiles />
              <div className="files-note">
                Bundled documents: in this preview they download as PDFs rebuilt
                from the embedded page images. On your deployed site the buttons
                pull the full-resolution originals from{" "}
                <code>/assets/certs/</code> automatically.
              </div>
              <FileGroup
                title="Certificates, Awards & Letters"
                docs={certDocs}
              />
              <FileGroup title="Education & Apprenticeships" docs={eduList} />
            </div>
          </div>
        );
      }

      // ---- Certificate viewer modal ----
      function docTitleFor(file) {
        const all = [].concat(CERTS, EDU_DEGREES, [EDU_JST], APPRENTICE);
        for (let i = 0; i < all.length; i++) {
          if (all[i] && all[i].file === file)
            return all[i].t || all[i].ti || file;
        }
        return file;
      }
      let _openCertViewer = null;
      function openCertViewer(file) {
        if (_openCertViewer) _openCertViewer(file);
      }
      function SummaryModal({ onClose }) {
        useEffect(() => {
          const onKey = (e) => {
            if (e.key === "Escape") onClose();
          };
          window.addEventListener("keydown", onKey);
          return () => window.removeEventListener("keydown", onKey);
        }, [onClose]);
        return (
          <div
            className="cv-bg sum-bg"
            onClick={onClose}
            role="dialog"
            aria-modal="true"
            aria-label="A short summary about Dustin"
          >
            <div
              className="cv-modal sum-modal"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="cv-head">
                <div
                  style={{
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 15,
                    letterSpacing: 0.4,
                  }}
                >
                  A Short Summary
                </div>
                <div className="cv-head-actions">
                  <button
                    className="cv-close"
                    aria-label="Close summary"
                    onClick={onClose}
                  >
                    ✕
                  </button>
                </div>
              </div>
              <div className="cv-body sum-body">
                <div className="sum-inner">
                  <p className="sum-lead">{SUMMARY_SHORT}</p>
                  <div className="sum-rule"></div>
                  {SUMMARY_FULL.map((p, i) => (
                    <p className="sum-p" key={i}>
                      {p}
                    </p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      }

      function CertViewer() {
        const [file, setFile] = useState(null);
        useEffect(() => {
          _openCertViewer = setFile;
          return () => {
            _openCertViewer = null;
          };
        }, []);
        useEffect(() => {
          const onKey = (e) => {
            if (e.key === "Escape") setFile(null);
          };
          if (file) window.addEventListener("keydown", onKey);
          return () => window.removeEventListener("keydown", onKey);
        }, [file]);
        if (!file) return null;
        const pages =
          window.CERT_IMAGES && window.CERT_IMAGES[file]
            ? window.CERT_IMAGES[file]
            : [];
        return (
          <div className="cv-bg" onClick={() => setFile(null)}>
            <div className="cv-modal" onClick={(e) => e.stopPropagation()}>
              <div className="cv-head">
                <FitTitle text={docTitleFor(file)} />
                <div className="cv-head-actions">
                  <button
                    className="cv-dl"
                    aria-label="Download PDF"
                    onClick={function () {
                      downloadCertPDF(file, docTitleFor(file)).catch(
                        function (e) {
                          alert(
                            "Could not prepare that file: " + (e.message || e),
                          );
                        },
                      );
                    }}
                  >
                    Open PDF ↗
                  </button>
                  <button
                    className="cv-close"
                    aria-label="Close viewer"
                    onClick={() => setFile(null)}
                  >
                    ✕
                  </button>
                </div>
              </div>
              <div className="cv-body">
                {pages.length ? (
                  pages.map((src, i) => (
                    <img
                      key={i}
                      src={src}
                      className="cv-img"
                      alt={"Document page " + (i + 1)}
                    />
                  ))
                ) : (
                  <iframe
                    className="cv-pdf"
                    src={"assets/certs/" + encodeURIComponent(file)}
                    title={docTitleFor(file)}
                  />
                )}
              </div>
            </div>
          </div>
        );
      }

      function App() {
        const [page, setPage] = useState("about");
        const [loading, setLoading] = useState(false);
        const [keyModal, setKeyModal] = useState(false);
        const [isAdmin, setIsAdmin] = useState(false);

        useEffect(() => {
          var b = document.getElementById("boot");
          if (!b) return;
          requestAnimationFrame(function () {
            b.classList.add("boot-done");
          });
          setTimeout(function () {
            if (b.parentNode) {
              b.parentNode.removeChild(b);
            }
          }, 1200);
        }, []);

        const go = (p) => {
          if (p === page) return;
          setLoading(true);
          setTimeout(() => {
            setPage(p);
            window.scrollTo(0, 0);
            setLoading(false);
          }, 380);
        };

        const pages = {
          about: <About go={go} onUnlock={() => setKeyModal(true)} />,
          experience: <Experience />,
          acknowledgements: <Acknowledgements />,
          projects: <Projects go={go} />,
          hobbies: <Hobbies />,
          contact: <Contact />,
          compile: (
            <CompilePage isAdmin={isAdmin} onUnlock={() => setIsAdmin(true)} />
          ),
          files: (
            <FilesPage isAdmin={isAdmin} onUnlock={() => setIsAdmin(true)} />
          ),
          hypeteen: <HypeTeenAcademy go={go} />,
          updates: (
            <UpdatesPage isAdmin={isAdmin} onUnlock={() => setIsAdmin(true)} />
          ),
          "manage-documents": isAdmin ? (
            <ManageDocumentsPage />
          ) : (
            <AdminHub
              isAdmin={isAdmin}
              onUnlock={() => setIsAdmin(true)}
              go={go}
            />
          ),
          "manage-experience": isAdmin ? (
            <ManageExperiencePage />
          ) : (
            <AdminHub
              isAdmin={isAdmin}
              onUnlock={() => setIsAdmin(true)}
              go={go}
            />
          ),
          admin: (
            <AdminHub
              isAdmin={isAdmin}
              onUnlock={() => setIsAdmin(true)}
              go={go}
            />
          ),
          apps: <AppLibraryPage go={go} />,
          tunes: <TunesPage go={go} />,
        };

        return (
          <div>
            <Masthead page={page} go={go} isAdmin={isAdmin} />
            {loading && <Spinner label="Loading" />}
            {pages[page] || pages.about}
            <Footer />
            {keyModal && (
              <KeyModal
                onClose={() => setKeyModal(false)}
                onSuccess={() => {
                  setIsAdmin(true);
                  setKeyModal(false);
                  go("admin");
                }}
              />
            )}
            <CertViewer />
            {isAdmin && (
              <div
                className="admin-banner"
                onClick={() => setIsAdmin(false)}
                title="Click to lock"
              >
                ● Admin Unlocked
              </div>
            )}
          </div>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<App />);
